import type { BigNumberData } from 'components/BigNumber/types';

import type { PortfolioCardData, PortfolioPieChartData } from '../types';

export const mockPortfolioBigNumbers: PortfolioCardData[] = [
  {
    id: 'activeInnoSkus',
    header: {
      title: 'Active Inno SKUs',
      measure: '#',
      period: "YTD May'26",
    },
    data: [
      {
        bigNumber: { value: '00.000' },
        comparison: {
          label: 'vs',
          value: 'LY',
          number: {
            value: '+0.0',
            measure: '%',
            trend: 'positive',
            color: '#007800',
          },
        },
      } satisfies BigNumberData,
    ],
  },
  {
    id: 'skuAverageSize',
    header: {
      title: 'SKU average size',
      measure: 'hl/SKU',
      period: "YTD May'26",
    },
    data: [
      {
        bigNumber: { value: '00.0' },
        comparison: {
          label: 'vs',
          value: 'LY',
          number: {
            value: '+0.0',
            measure: '%',
            trend: 'positive',
            color: '#007800',
          },
        },
      } satisfies BigNumberData,
    ],
  },
];

export const mockPortfolioPieCharts: PortfolioPieChartData[] = [
  {
    id: 'liquidType',
    title: 'Innovation Liquid Type',
    slices: [
      { label: 'Beer', percentage: 25 },
      { label: 'Beyond Beer', percentage: 25 },
      { label: 'NABEV', percentage: 25 },
      { label: 'Nab-Beer', percentage: 25 },
    ],
  },
  {
    id: 'innovationPillar',
    title: 'Innovation Pillar',
    slices: [
      { label: 'New Opportunities', percentage: 33 },
      { label: 'Pack & Price', percentage: 33 },
      { label: 'Renovation', percentage: 34 },
    ],
  },
  {
    id: 'megabrandFramework',
    title: 'Megabrand Framework',
    slices: [
      { label: 'Megabrands', percentage: 25 },
      { label: 'Expansion', percentage: 25 },
      { label: 'Sustain', percentage: 25 },
      { label: 'Tail', percentage: 25 },
    ],
  },
];
